import Foundation
import CryptoKit
import XCTest

@testable import IrohaSwift

/// Model-generated byte parity and refusal controls. Synthetic proofs never qualify a prover.
final class PrivacyX509TransactionV1Tests: XCTestCase {
    private typealias Wire = PrivacyX509WireV1

    func testDirectPlanAndSignedWireMatchRegeneratedNativeFixture() throws {
        let row = try nativeRow()
        let (plan, proof) = try planAndProof(row)
        XCTAssertEqual(plan.materializedStatement, row.statementNorito)
        XCTAssertEqual(plan.actionStatement, row.transactionIntentProjectionNorito)
        XCTAssertEqual(plan.actionDigest, row.transactionIntentDigest)
        XCTAssertEqual(try plan.completedPayload(rawProof: proof, limits: limits()),
                       row.unsignedTransactionPayloadNorito)
        // The model's exact12_signing_key_pair_v1 uses this public deterministic seed.
        let key = try SigningKey.ed25519(privateKey: Data(repeating: 0xe7, count: 32))
        let authority = try Keypair(privateKeyBytes: Data(repeating: 0xe7, count: 32)).accountId()
        let signed = try plan.sign(rawProof: proof, limits: limits(), authority: authority, signingKey: key)
        XCTAssertEqual(signed.norito.first, 1)
        let signedFields = try Wire.split(Data(signed.norito.dropFirst()), count: 3, maximum: 16 * 1024 * 1024)
        let fixtureFields = try Wire.split(Data(row.signedTransactionVersionedNorito.dropFirst()),
                                          count: 3, maximum: 16 * 1024 * 1024)
        XCTAssertEqual(signedFields[1], row.unsignedTransactionPayloadNorito)
        XCTAssertEqual(signedFields[2], fixtureFields[2])

        // CryptoKit may randomize Ed25519 signatures. Pin serialization with the
        // model's signature, then verify the actual platform signature independently.
        let fixtureSignature = try signatureBytes(fixtureFields[0])
        let fixtureEnvelope = SingleInstructionSwiftNoritoEncoder.signedEnvelope(
            transactionPayload: signedFields[1], signature: fixtureSignature
        )
        XCTAssertEqual(fixtureEnvelope.norito, row.signedTransactionVersionedNorito)
        let signature = try signatureBytes(signedFields[0])
        let publicKey = try key.publicKey()
        let message = IrohaHash.hash(signedFields[1])
        for candidate in [fixtureSignature, signature] {
            XCTAssertEqual(NoritoNativeBridge.shared.verifyDetached(
                algorithm: .ed25519, publicKey: publicKey, message: message, signature: candidate
            ), true)
        }
        var changedSignature = signature
        changedSignature[changedSignature.startIndex] ^= 1
        XCTAssertEqual(NoritoNativeBridge.shared.verifyDetached(
            algorithm: .ed25519, publicKey: publicKey, message: message, signature: changedSignature
        ), false)
        var changedPayload = signedFields[1]
        changedPayload[changedPayload.startIndex] ^= 1
        XCTAssertEqual(NoritoNativeBridge.shared.verifyDetached(
            algorithm: .ed25519, publicKey: publicKey,
            message: IrohaHash.hash(changedPayload), signature: signature
        ), false)
        XCTAssertEqual(signed.transactionHash, row.signedTransactionHash)
        try Wire.validateFixture(row)
    }

    private func signatureBytes(_ transactionSignature: Data) throws -> Data {
        let vector = try Wire.split(transactionSignature, count: 1, maximum: 136)[0]
        XCTAssertEqual(vector.prefix(8), Wire.u64(64))
        let bytes = try Wire.split(Data(vector.dropFirst(8)), count: 64, maximum: 1)
        return Data(try bytes.map { try XCTUnwrap($0.first) })
    }

    func testGeneratedProofChangesSignedOccurrenceButNeverPreparedStatement() throws {
        let row = try nativeRow()
        let (plan, proof) = try planAndProof(row)
        var changedProof = proof
        changedProof[changedProof.startIndex] ^= 1
        let first = try plan.completedPayload(rawProof: proof, limits: limits())
        let second = try plan.completedPayload(rawProof: changedProof, limits: limits())
        XCTAssertNotEqual(first, second)
        let firstFields = try Wire.split(first, count: 9, maximum: 16 * 1024 * 1024)
        let secondFields = try Wire.split(second, count: 9, maximum: 16 * 1024 * 1024)
        for index in 0..<8 { XCTAssertEqual(firstFields[index], secondFields[index]) }
        XCTAssertNotEqual(firstFields[8], secondFields[8])
        XCTAssertEqual(plan.materializedStatement, row.statementNorito)
        XCTAssertEqual(plan.actionDigest, row.transactionIntentDigest)
        var reconstructed = secondFields
        reconstructed[8] = Data([0])
        let rebuilt = try Wire.prepareDirect(requestArchive: row.submitProofInstructionNorito,
                                            unsignedPayload: Wire.fields(reconstructed))
        XCTAssertEqual(rebuilt.orderedIntentDigest, plan.orderedIntentDigest)
        XCTAssertEqual(rebuilt.actionStatement, plan.actionStatement)
    }

    func testDirectPlanBindsOriginalTransactionFieldsAndRefusesOtherAuthorityShapes() throws {
        let row = try nativeRow()
        let (plan, _) = try planAndProof(row)
        var base = try Wire.split(row.unsignedTransactionPayloadNorito, count: 9, maximum: 16 * 1024 * 1024)
        base[8] = Data([0])
        // Independent time, lifetime, nonce and metadata are retained verbatim in ordered intent.
        let independentChanges: [(Int, Data)] = [
            (2, Wire.u64(1_700_000_000_006)),
            (4, Data([1]) + Wire.fields([Wire.u64(60_001)])),
            (5, Data([1]) + Wire.fields([Wire.u32(7)])),
            (7, try CanonicalNorito.encodeCompactMetadata(["memo": .string("different")])),
        ]
        for (index, value) in independentChanges {
            var changed = base
            changed[index] = value
            let candidate = try Wire.prepareDirect(requestArchive: row.submitProofInstructionNorito,
                                                   unsignedPayload: Wire.fields(changed))
            XCTAssertNotEqual(candidate.orderedIntentDigest, plan.orderedIntentDigest)
            XCTAssertNotEqual(candidate.actionDigest, plan.actionDigest)
        }
        for index in [0, 1, 3, 8] {
            var changed = base
            changed[index].append(0x31)
            XCTAssertThrowsError(try Wire.prepareDirect(requestArchive: row.submitProofInstructionNorito,
                                                       unsignedPayload: Wire.fields(changed)))
        }
        for reference in [Wire.fields([Wire.u32(1), Wire.u32(0)]),
                          Wire.fields([Wire.u32(0), Wire.u32(1)])] {
            let request = try requestFields(row)
            let archive = Wire.frame(Wire.fields([request[0], reference]), schema: Wire.requestSchema, alignment: 8)
            XCTAssertThrowsError(try Wire.prepareDirect(requestArchive: archive, unsignedPayload: Wire.fields(base)))
        }
        let wrongKey = try SigningKey.ed25519(privateKey: Data(repeating: 0x11, count: 32))
        let authority = try Keypair(privateKeyBytes: Data(repeating: 0xe7, count: 32)).accountId()
        XCTAssertThrowsError(try plan.sign(rawProof: Data([1]), limits: limits(),
                                         authority: authority, signingKey: wrongKey))
    }

    func testCapabilityProjectionRequiresZeroIntentExactNetworkAndEveryProfileDigest() throws {
        let fixture = try nativeRow()
        let request = try Wire.parseRequest(fixture.submitProofInstructionNorito)
        let network = try NetworkId(bytes: request.context[0])
        let tuple = try request.context.dropFirst(3).map { try Wire.digest($0) }
        let protocolId = PrivacyProtocolIdV1.irohaZkX509StarkP256V1
        // A parser projection is not an opaque native/network admission token.
        let profile = PrivacyCompiledProfileSnapshotV1(
            protocolId: protocolId, proofSystemId: protocolId.expectedProofSystem,
            engineId: protocolId.expectedEngine, parameterId: tuple[0], parameterDigest: tuple[1],
            verifierDigest: tuple[2], statementSchemaDigest: tuple[3], engineManifestDigest: tuple[4],
            protocolLimits: PrivacyProtocolLimitsV1(protocolId: protocolId, values: [], canonicalNorito: Data())
        )
        let row = PrivacyExact12CapabilityRowV1(
            protocolId: protocolId, operationSchema: .zkX509IdentityPresentationV1,
            executionMode: .presentationAction, privacyFeatureMask: 0, compiledProfile: .available(profile),
            readiness: .available, policy: nil,
            localCompiledTupleMatches: false, compiledProfileCanonicalNorito: Data()
        )
        try PrivacyExact12CapabilityManifestCodecV1.requireSubmitProofInstruction(
            fixture.submitProofInstructionNorito, row: row, consensusLimits: limits(), expectedNetworkId: network
        )
        for index in 0..<8 where index != 1 {
            let bad = try mutateRequest(fixture) { statement in
                var context = try Wire.split(statement[0], count: 8, maximum: Wire.statementLimit)
                context[index][context[index].index(before: context[index].endIndex)] ^= 1
                statement[0] = Wire.fields(context)
            }
            XCTAssertThrowsError(try PrivacyExact12CapabilityManifestCodecV1.requireSubmitProofInstruction(
                bad, row: row, consensusLimits: limits(), expectedNetworkId: network
            ))
        }
        let generic = Wire.frame(Wire.fields([try Wire.canonicalFrame(fixture.envelopeNorito,
            schema: "iroha.privacy.proof-envelope.v1", alignment: 16, maximum: 512 * 1024)]),
            schema: "iroha_data_model::isi::privacy::SubmitPrivacyProofV1", alignment: 16)
        XCTAssertThrowsError(try PrivacyExact12CapabilityManifestCodecV1.requireSubmitProofInstruction(
            generic, row: row, consensusLimits: limits(), expectedNetworkId: network
        ))
        XCTAssertThrowsError(try Wire.parseRequest(fixture.submitProofInstructionNorito + Data([0])))
        XCTAssertThrowsError(try Wire.parseRequest(Data(repeating: 0, count: Wire.requestLimit + 1)))
        XCTAssertEqual(PrivacyExact12FixtureCodecV1.instructionWireId(for: protocolId), Wire.wireId)
        for other in PrivacyProtocolIdV1.allCases where other != protocolId {
            XCTAssertEqual(PrivacyExact12FixtureCodecV1.instructionWireId(for: other),
                           PrivacyExact12FixtureCodecV1.submitProofWireId)
        }
    }

    func testProofBoundsAreExactAndSigningNeverRewritesAuthority() throws {
        let row = try nativeRow()
        let (plan, proof) = try planAndProof(row)
        let exactCharge = UInt32(row.submitProofInstructionNorito.count + proof.count)
        _ = try plan.completedPayload(rawProof: proof, limits: limits(actionBytes: exactCharge))
        XCTAssertThrowsError(try plan.completedPayload(rawProof: proof, limits: limits(actionBytes: exactCharge - 1)))
        XCTAssertThrowsError(try plan.completedPayload(rawProof: proof, limits: limits(proofBytes: UInt32(proof.count - 1))))
        for bad in [Data(), Data(repeating: 0, count: proof.count)] {
            XCTAssertThrowsError(try plan.completedPayload(rawProof: bad, limits: limits()))
        }
        let key = try SigningKey.ed25519(privateKey: Data(repeating: 0xe7, count: 32))
        let wrongAuthority = try Keypair(privateKeyBytes: Data(repeating: 0x11, count: 32)).accountId()
        XCTAssertThrowsError(try plan.sign(rawProof: proof, limits: limits(), authority: wrongAuthority, signingKey: key))
        let wrongKey = try SigningKey.ed25519(privateKey: Data(repeating: 0x11, count: 32))
        XCTAssertThrowsError(try plan.sign(rawProof: proof, limits: limits(), authority: wrongAuthority, signingKey: wrongKey))
    }

    func testFixtureRejectsOccurrenceActionAndIndependentInputSubstitutions() throws {
        let row = try nativeRow()
        for index in [0, 1, 2, 3, 4, 5, 6, 7, 8] {
            var unsigned = try Wire.split(row.unsignedTransactionPayloadNorito, count: 9, maximum: 16 * 1024 * 1024)
            unsigned[index].append(0x61)
            let changed = try copyRow(row, unsigned: Wire.fields(unsigned))
            XCTAssertThrowsError(try Wire.validateFixture(changed))
        }
        for field in [1, 3, 5, 7, 9, 10, 18, 19] {
            let bad = try mutateRequest(row) { statement in
                statement[field][statement[field].index(before: statement[field].endIndex)] ^= 1
            }
            XCTAssertThrowsError(try Wire.validateFixture(try copyRow(row, request: bad)))
        }
        var attachments = try Wire.split(row.unsignedTransactionPayloadNorito, count: 9, maximum: 16 * 1024 * 1024)
        // Every action/reference/occurrence byte is fixed by the expected canonical owner.
        for offset in attachments[8].indices {
            var changed = attachments
            changed[8][offset] ^= 1
            XCTAssertThrowsError(try Wire.validateFixture(try copyRow(row, unsigned: Wire.fields(changed))))
        }
        attachments[8] = Data([0])
        XCTAssertThrowsError(try Wire.validateFixture(try copyRow(row, unsigned: Wire.fields(attachments))))
    }

    func testSharedBlake3PreservesKnownAnswerAndLengthFraming() throws {
        XCTAssertEqual(try XCTUnwrap(Blake3.hash(Data())).hexEncodedString(),
                       "af1349b9f5f9a1a6a0404dea36dcc9499bcb25c9adc112b7cc9a93cae41f3262")
        XCTAssertThrowsError(try Wire.split(Data([0x81, 0, 1]), count: 1, maximum: 1))
        XCTAssertThrowsError(try Wire.split(Data([2, 1]), count: 1, maximum: 1))
        XCTAssertThrowsError(try Wire.integer32(Data([1, 2, 3])))
        let bytes = Data([1, 2, 3])
        XCTAssertEqual(try Wire.domainHash("test", bytes),
                       try Wire.hash(Data("test".utf8) + Wire.u64(3) + bytes))
        XCTAssertNotEqual(try Wire.domainHash("test", bytes), try Wire.domainHash("tes", Data([116]) + bytes))
    }

    private func limits(actionBytes: UInt32 = 9_699_840, proofBytes: UInt32 = 9_437_184) -> PrivacyConsensusLimitsV1 {
        PrivacyConsensusLimitsV1(maxActionsPerTransaction: 1, maxActionsPerBlock: 2,
            maxProofBytesPerAction: proofBytes, maxActionBytes: actionBytes,
            maxPrivacyBytesPerTransaction: actionBytes, maxPrivacyBytesPerBlock: 16_711_680,
            maxStatementAndEncryptedOutputBytesPerTransaction: 262_144,
            maxNullifiersPerAction: 8, maxCommitmentsPerAction: 8, retainedRootCount: 2048)
    }

    private func planAndProof(_ row: PrivacyExact12TypedFixtureRowV1) throws -> (Wire.DirectPlan, Data) {
        var unsigned = try Wire.split(row.unsignedTransactionPayloadNorito, count: 9, maximum: 16 * 1024 * 1024)
        unsigned[8] = Data([0])
        let plan = try Wire.prepareDirect(requestArchive: row.submitProofInstructionNorito,
                                          unsignedPayload: Wire.fields(unsigned))
        let envelope = try Wire.canonicalFrame(row.envelopeNorito, schema: "iroha.privacy.proof-envelope.v1",
                                               alignment: 16, maximum: 512 * 1024)
        let fields = try Wire.split(envelope, count: 13, maximum: 512 * 1024)
        let wrapper = try Wire.split(Data(fields[12].dropFirst(4)), count: 1, maximum: 512 * 1024)[0]
        let vector = try Wire.split(wrapper, count: 1, maximum: 512 * 1024)[0]
        return (plan, try Wire.rawVector(vector, maximum: Wire.maximumProofBytes))
    }

    private func requestFields(_ row: PrivacyExact12TypedFixtureRowV1) throws -> [Data] {
        try Wire.split(Wire.canonicalFrame(row.submitProofInstructionNorito, schema: Wire.requestSchema,
                                          alignment: 8, maximum: Wire.requestLimit), count: 2, maximum: Wire.statementLimit)
    }
    private func mutateRequest(_ row: PrivacyExact12TypedFixtureRowV1,
                               _ edit: (inout [Data]) throws -> Void) throws -> Data {
        var request = try requestFields(row)
        var statement = try Wire.split(request[0], count: 20, maximum: Wire.statementLimit)
        try edit(&statement)
        request[0] = Wire.fields(statement)
        return Wire.frame(Wire.fields(request), schema: Wire.requestSchema, alignment: 8)
    }
    private func copyRow(_ row: PrivacyExact12TypedFixtureRowV1, request: Data? = nil,
                         unsigned: Data? = nil) throws -> PrivacyExact12TypedFixtureRowV1 {
        try PrivacyExact12TypedFixtureRowV1(protocolId: row.protocolId,
            statementNorito: row.statementNorito, envelopeNorito: row.envelopeNorito,
            submitProofWireId: row.submitProofWireId, submitProofInstructionNorito: request ?? row.submitProofInstructionNorito,
            transactionIntentProjectionNorito: row.transactionIntentProjectionNorito,
            transactionIntentDigest: row.transactionIntentDigest,
            unsignedTransactionPayloadNorito: unsigned ?? row.unsignedTransactionPayloadNorito,
            signedTransactionVersionedNorito: row.signedTransactionVersionedNorito,
            signedTransactionHash: row.signedTransactionHash)
    }
    private func nativeRow() throws -> PrivacyExact12TypedFixtureRowV1 {
        var directory = URL(fileURLWithPath: #filePath).deletingLastPathComponent()
        while directory.path != "/" {
            let file = directory.appendingPathComponent("fixtures/privacy/exact12_typed_fixture_bundle_v1.norito.b64")
            if FileManager.default.fileExists(atPath: file.path) {
                let text = try String(contentsOf: file, encoding: .utf8)
                let bundle = try PrivacyExact12FixtureCodecV1.decodeCanonicalBase64File(text)
                return try XCTUnwrap(bundle.rows.first { $0.protocolId == .irohaZkX509StarkP256V1 })
            }
            directory.deleteLastPathComponent()
        }
        throw Wire.invalid("missing genuinely regenerated native Exact12 fixture")
    }
}
